# n32 Restaurant round 2 (Sam 20 Oct): 'now do 20 more'. 'be consistent, we now have table materials that we can use, use what is needed when needed'.
# Pins: marble = use when needed, likes the glass lights; bronze table + glass + materials work but comp too similar to the figma; olive linen = use linen but NOT that colour, no inspo green, glass should not look fallen;
# white tablecloth = 'i like all. elegant'; walnut = don't use now.
# So the material kit is: white marble, ivory oat linen, crisp white tablecloth, polished bronze. Clear crystal glass, upright. No green, no walnut. New comps, not the moodboard's.
import importlib.util,os
_s=importlib.util.spec_from_file_location('r1',os.path.join(os.path.dirname(__file__),'n32r1_table.py'));r1=importlib.util.module_from_spec(_s);_s.loader.exec_module(r1)
C1,CARD,sh=r1.C,r1.CARD,r1.sh
C=dict(C1)
C['id']='n32r2'
C['world']=('A refined restaurant and bar, always built from the same four table materials: polished white Calacatta marble with soft grey veins, warm ivory oat-coloured linen, a crisp white cotton tablecloth, '
            'and polished warm bronze; clear crystal glassware standing upright; nothing else unless the shot names it.')
C['palette']='Warm and rich: creamy marble whites, ivory and oat linen, warm bronze and amber, inky shadows; no green anywhere; the design surface clean warm white. The same grade on every image of the collection.'
C['avoid']=C1['avoid']+['any green tone, green glass or green cloth, walnut or dark wood','a glass lying on its side or spilled']
RD=lambda w: f'THE {w} IS PLAIN THICK WARM WHITE ROUND BOARD, flat with a crisp edge, nothing printed on it.'
P=lambda w: f'THE {w} IS PLAIN WARM WHITE UNCOATED PAPER, flat and crisp, nothing printed on it.'
